const doc = wwLib && wwLib.getFrontDocument ? wwLib.getFrontDocument() : document;

if (win.__wwJournalDeckTimer) {
  win.clearInterval(win.__wwJournalDeckTimer);
}
const total = 8;
const expandedSlugUid = 'f0b7a868-ce5e-4e70-a282-c2ab4d4476be';
const pausedUid = 'a73fe533-43b1-47c1-b575-ab3eb7629ceb';
const indexUid = '84c22461-3003-4424-bc50-be3b705b2ccd';

win.__wwJournalDeckTimer = win.setInterval(function () {
  const isExpanded = variables[expandedSlugUid];
  const isPaused = variables[pausedUid];
  if (isExpanded || isPaused) {
    return;
  }

  let current = variables[indexUid] || 0;
  current = (current + 1) % total;

  if (wwLib && wwLib.wwVariable && wwLib.wwVariable.updateValue) {
    wwLib.wwVariable.updateValue(indexUid, current);
  }

  const el = doc.getElementById('ww-deck-card-' + current);
  if (el) {
    el.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
  }
}, 5000);

return true;

