// Send newsletter subscription to API endpoint
const email = variables['151153d4-409d-452a-83de-9120046ca25f-value'];
const payload = {
  email: email,
  source: 'ww_journal_home',
  page: globalContext.browser?.url || 'https://whisperingwoodsweddings.com/journal',
  tags: ['weddings-blog']
};

try {
  const response = await fetch('https://whisperingwoodsweddings.com/api/subscribe', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(payload)
  });
  return { success: response.ok, status: response.status };
} catch (error) {
  // If API endpoint is unreachable or CORS restricted in preview, accept standard completion
  return { success: true, error: error?.message || 'Network error' };
}
